"""Fixed vendor log parser for maintenance log analysis."""

import csv
import sys


def summarize(path: str) -> dict[str, int]:
    counts = {"ok": 0, "malformed": 0, "high": 0}
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            # Bug 1 fix: Check if temperature exists and is not empty
            temp_str = row.get("temperature_c", "")
            if not temp_str:
                counts["malformed"] += 1
                continue
            try:
                temperature = float(temp_str)
            except ValueError:
                counts["malformed"] += 1
                continue

            # Bug 2 fix: Vendor's 350.0 limit is inclusive, so > 350.0 is high
            if temperature > 350.0:
                counts["high"] += 1
            else:
                counts["ok"] += 1
    return counts


if __name__ == "__main__":
    print(summarize(sys.argv[1]))
